arguments.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
    overflow-y: auto;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

.channel-list {
    list-style: none;
    margin: 0;
    padding: 8px;
}

.channel-item {
    padding: 10px 12px;
    border-radius: 6px;
    cursor: pointer;
    position: relative;
    margin-bottom: 2px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #404449;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    margin-bottom: 2px;
}

.channel-description {
    font-size: 0.78rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 10px;
    right: 10px;
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main message area */
.message-area {
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    transition: width 0.2s ease;
}

.message-area.full-width {
    width: 80%;
}

.message-area.with-thread {
    width: 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.message-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.82rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8e9297;
    font-size: 0.85rem;
}

.message-item {
    padding: 8px 12px;
    border-radius: 6px;
    position: relative;
    margin-bottom: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #32353b;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    font-size: 0.92rem;
    color: #fff;
}

.message-time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    font-size: 0.92rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* Reactions */
.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #4f545c;
}

/* Thread link */
.thread-link {
    display: inline-block;
    margin-top: 4px;
    font-size: 0.8rem;
    color: #00aff4;
    cursor: pointer;
    text-decoration: none;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Message actions */
.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    z-index: 10;
}

.action-btn {
    background: transparent;
    border: none;
    color: #b9bbbe;
    font-size: 0.78rem;
    padding: 4px 8px;
    border-radius: 4px;
    cursor: pointer;
    white-space: nowrap;
}

.action-btn:hover {
    background: #4f545c;
    color: #fff;
}

/* Emoji picker */
.emoji-picker {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 8px;
    padding: 6px 8px;
    width: fit-content;
}

.emoji-btn {
    background: transparent;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.15s;
}

.emoji-btn:hover {
    background: #4f545c;
}

/* Message input */
.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #202225;
    flex-shrink: 0;
}

.message-input {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.9rem;
    resize: none;
    min-height: 40px;
    max-height: 120px;
    font-family: inherit;
}

.message-input:focus {
    outline: none;
    box-shadow: 0 0 0 2px #5865f2;
}

.message-input::placeholder {
    color: #72767d;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* No channel selected */
.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #8e9297;
    font-size: 1.1rem;
}

/* Thread panel */
.thread-panel {
    width: 25%;
    min-width: 260px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: transparent;
    border: none;
    color: #b9bbbe;
